da78288e05d07b552c5303c08721c', '1994-11-09', 'male', 'San Jose, California', 'San Diego, California', 'Evidence and records technician · Pacific Ridge Police Department', 'Maintains the evidence inventory, verifies intake records and prepares material for authorized case review. Supports investigators with organized attachments, equipment checks and accurate records of every evidence transfer.', '+1 619 555 0103', 'https://pacific-ridge.example.com', '[{"label": "Professional profile", "url": "https://pacific-ridge.example.com/team/daniel-kim"}, {"label": "Work group", "url": "https://pacific-ridge.example.com/team"}]', '3ce5cf2c15d1540882ef55c98826187f', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:56');
